### C++

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

// 树状数组（Binary Indexed Tree），用于计算逆序数
struct BIT {
    int n;
    vector<int> tree;
    BIT(int n): n(n), tree(n+1, 0) {}
    // 更新下标i，增加val
    void update(int i, int val) {
        for(; i <= n; i += i & -i)
            tree[i] += val;
    }
    // 查询前缀和[1, i]
    int query(int i) {
        int res = 0;
        for(; i > 0; i -= i & -i)
            res += tree[i];
        return res;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> t(n);
    for (int i = 0; i < n; i++){
        cin >> t[i];
    }

    // 根据k值分情况讨论
    if(k >= 3){

        cout << 0 << "\n";
    }
    else if(k == 1){
        // 当k = 1时，只能交换相差1的碎片，
        // 这相当于只能进行相邻交换，最少代价等于逆序数
        ll inv = 0;
        BIT bit(n);
        // 逆序数算法：从左到右统计比当前大且出现过的数字个数
        for(int i = 0; i < n; i++){
            // 查询t[i]左侧已有数字中大于t[i]的个数
            inv += i - bit.query(t[i]);
            bit.update(t[i], 1);
        }
        cout << inv << "\n";
    }
    else if(k == 2){
        // 当k = 2时，只能免费交换两个相差2的数字，
        // 这使得所有奇数之间可免费交换，偶数之间可免费交换，
        // 而奇偶之间交换必须付费（代价为1）
        // 故最终有序序列中，奇数必出现在位置1,3,5,.......
        // 偶数必出现在位置2,4,6,......
        // 利用免费交换可以任意调换同组内顺序，
        // 故只需要计算将原排列中奇数移动到预定奇数位置所需的步数即可。

        vector<int> posOdd;  // 存储原序列中奇数所在的位置（下标从1开始）
        for (int i = 0; i < n; i++){
            if(t[i] & 1) posOdd.push_back(i+1);
        }
        ll ans = 0;
        // 设奇数个数为m，目标奇数位置为1,3,5,......,2m-1
        for (int i = 0; i < posOdd.size(); i++){
            int target = 2*i + 1;
            ans += abs(posOdd[i] - target);
        }
        cout << ans << "\n";
    }

    return 0;
}
