import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:]))

    if k >= 3:
        # k >= 3 时，可以不消耗魔力完成排序
        print(0)
    elif k == 1:
        # k = 1 只能相邻交换，最小代价 = 逆序数
        class BIT:
            def __init__(self, n):
                self.n = n
                self.tree = [0] * (n + 1)
            def update(self, i, delta):
                while i <= self.n:
                    self.tree[i] += delta
                    i += i & -i
            def query(self, i):
                s = 0
                while i > 0:
                    s += self.tree[i]
                    i -= i & -i
                return s

        bit = BIT(n)
        inv = 0
        for i in range(n):
            # 当前数字 a[i] 左侧已有数字中大于 a[i] 的个数
            inv += i - bit.query(a[i])
            bit.update(a[i], 1)
        print(inv)
    elif k == 2:
        # k = 2 时，所有奇数之间免费交换，所有偶数之间免费交换
        # 奇偶之间交换消耗1点魔力，目标奇数位置为 1,3,5,...
        pos_odd = []  # 存储原序列中奇数魔力等级的位置，从1开始
        for i in range(n):
            if a[i] % 2 == 1:
                pos_odd.append(i + 1)
        ans = 0
        for i, pos in enumerate(pos_odd):
            target = 2 * i + 1   # 第 i+1 个奇数应该处于的位置
            ans += abs(pos - target)
        print(ans)

if __name__ == "__main__":
    solve()
